// Precedence Example: *, / higher than +, -
int x = 10 + 5 * 2;     // Evaluates as 10 + (5 * 2)
// x is 20, not (10 + 5) * 2 = 30

// Associativity Example: Arithmetic is Left-to-Right
int y = 20 / 4 * 5;     // Evaluates as (20 / 4) * 5
// y is 25, not 20 / (4 * 5) = 1

// Assignment is Right-to-Left
int a, b, c;
a = b = c = 50;         // Evaluates as a = (b = (c = 50));

// Short-circuiting (Logical Operators &&, ||)
bool check = (false && (1 / 0)); // No crash (right operand skipped)
bool result = (true || expensive_call()); // expensive_call skipped

// Use Parentheses to override or clarify
int z = (10 + 5) * 2;   // z is 30
